MAX_LENGTH = 200


def shorten(line):
    """Cut a Unicode line to the longest text a notification may carry."""
    return line[:MAX_LENGTH]


def message(args):
    """Build the text of a notification without lossy ASCII conversion."""
    body = args.get("text", "")
    who = args.get("mention")
